const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const os = require('os');

class DistributedCacheClient {
  constructor(options = {}) {
    this.nodes = options.nodes || ['localhost:6379'];
    this.prefix = options.prefix || 'dcache';
    this.ttl = options.ttl || 3600;
    this.localSpillDir = options.localSpillDir || this._resolveSpillDir();
    this.maxMemoryItems = options.maxMemoryItems || 1000;
    this.memCache = new Map();
    this._initialized = false;
  }

  _resolveSpillDir() {
    const envDir = process.env.DCACHE_SPILL_DIR;
    const baseDir = envDir || path.join(os.tmpdir(), 'dcache-spill');
    const instanceId = crypto.randomBytes(8).toString('hex');
    return path.join(baseDir, instanceId);
  }

  async initialize() {
    if (this._initialized) return;
    await this._ensureSpillDirectory();
    this._initialized = true;
  }

  async _ensureSpillDirectory() {
    const dir = this.localSpillDir;
    try {
      const stats = fs.statSync(dir);
      if (!stats.isDirectory()) {
        throw new Error(`Spill path exists but is not a directory: ${dir}`);
      }
    } catch (e) {
      if (e.code === 'ENOENT') {
        fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
      } else if (!e.message.includes('not a directory')) {
        throw e;
      }
    }
  }

  _computeSlot(key) {
    const hash = crypto.createHash('sha256').update(key).digest();
    return hash.readUInt16BE(0) % 16384;
  }

  _getNodeForSlot(slot) {
    const nodeIndex = slot % this.nodes.length;
    return this.nodes[nodeIndex];
  }

  _spillPathForKey(key) {
    const safeKey = crypto.createHash('sha256').update(key).digest('hex');
    const subdir = safeKey.substring(0, 2);
    return path.join(this.localSpillDir, subdir, safeKey);
  }

  async get(key) {
    if (!this._initialized) await this.initialize();
    const fullKey = `${this.prefix}:${key}`;

    if (this.memCache.has(fullKey)) {
      const entry = this.memCache.get(fullKey);
      if (Date.now() < entry.expiry) return entry.value;
      this.memCache.delete(fullKey);
    }

    const spillPath = this._spillPathForKey(fullKey);
    return this._readFromSpill(spillPath);
  }

  async _readFromSpill(filePath) {
    try {
      const resolvedPath = path.resolve(filePath);
      if (!resolvedPath.startsWith(path.resolve(this.localSpillDir))) {
        throw new Error('Path traversal detected');
      }
      const data = fs.readFileSync(filePath, 'utf8');
      const parsed = JSON.parse(data);
      if (Date.now() < parsed.expiry) {
        return parsed.value;
      }
      fs.unlinkSync(filePath);
      return null;
    } catch (e) {
      if (e.code === 'ENOENT') return null;
      throw e;
    }
  }

  async set(key, value, ttl) {
    if (!this._initialized) await this.initialize();
    const fullKey = `${this.prefix}:${key}`;
    const effectiveTtl = ttl || this.ttl;
    const expiry = Date.now() + (effectiveTtl * 1000);

    if (this.memCache.size < this.maxMemoryItems) {
      this.memCache.set(fullKey, { value, expiry });
    } else {
      await this._writeToSpill(fullKey, value, expiry);
    }
  }

  async _writeToSpill(key, value, expiry) {
    const spillPath = this._spillPathForKey(key);
    const dir = path.dirname(spillPath);

    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    }

    const payload = JSON.stringify({ value, expiry, key });
    const tmpFile = spillPath + '.tmp.' + process.pid;
    fs.writeFileSync(tmpFile, payload, { mode: 0o600 });
    fs.renameSync(tmpFile, spillPath);
  }

  async cleanup() {
    const spillDir = this.localSpillDir;
    if (!fs.existsSync(spillDir)) return;

    const entries = this._walkDir(spillDir);
    for (const entry of entries) {
      try {
        const stat = fs.lstatSync(entry);
        if (stat.isSymbolicLink()) {
          fs.unlinkSync(entry);
          continue;
        }
        const data = fs.readFileSync(entry, 'utf8');
        const parsed = JSON.parse(data);
        if (Date.now() >= parsed.expiry) {
          fs.unlinkSync(entry);
        }
      } catch (e) { /* ignore cleanup errors */ }
    }
  }

  _walkDir(dir) {
    let results = [];
    try {
      const entries = fs.readdirSync(dir);
      for (const entry of entries) {
        const fullPath = path.join(dir, entry);
        const stat = fs.statSync(fullPath);
        if (stat.isDirectory()) {
          results = results.concat(this._walkDir(fullPath));
        } else {
          results.push(fullPath);
        }
      }
    } catch (e) { /* ignore */ }
    return results;
  }
}

module.exports = { DistributedCacheClient };
